package org.icu.sepsis.ai;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.util.*;import java.time.*;import org.junit.jupiter.api.Test;import org.icu.sepsis.notes.*;import org.icu.sepsis.domain.Domain.Patient;import org.icu.sepsis.application.Store;import org.springframework.data.mongodb.core.MongoTemplate;import org.springframework.data.mongodb.core.query.Query;import com.fasterxml.jackson.databind.ObjectMapper;
class ClinicalNoteAiEvidenceTest {
 final MongoTemplate db=mock(MongoTemplate.class);final Store store=new Store(db,"ICU",new ObjectMapper());final ClinicalNoteService notes=mock(ClinicalNoteService.class);final ClinicalNoteProperties props=new ClinicalNoteProperties();final ClinicalNoteAiEvidence evidence=new ClinicalNoteAiEvidence(store,notes,props);final Patient p=new Patient();
 ClinicalNoteAiEvidenceTest(){p.id="synthetic-patient";p.patientId=p.id;p.encounterId="synthetic-stay";p.department="ICU";p.label="合成姓名";}
 @Test void readsBoundedSnapshotsAndKeepsRawIdentifiersOutOfModelFacts(){var note=new ClinicalNoteSnapshot();note.id="internal-note-id";note.documentType="合成病程";note.documentedAt=Instant.parse("2026-01-01T00:00:00Z");note.cryptoVersion=1;when(db.find(any(Query.class),eq(ClinicalNoteSnapshot.class))).thenReturn(List.of(note));when(notes.read(p.id,note.id,"doctor")).thenReturn(Map.of("body","姓名：合成姓名\n考虑感染，尚需排除失血原因。"));var packet=evidence.collect(p,"doctor");assertEquals(1,packet.sources.size());assertEquals(false,packet.sources.get(0).get("timeConfirmed"));String facts=packet.facts.stream().map(a->a[1]).reduce("",String::concat);assertFalse(facts.contains("internal-note-id"));assertFalse(facts.contains("合成姓名"));assertTrue(facts.contains("文书时间未确认"));assertTrue(facts.contains("排除失血"));verify(notes).read(p.id,note.id,"doctor");verify(notes,never()).syncPatient(any());}
 @Test void unreadableSnapshotsCannotLeakExceptionOrBecomeNormal(){var note=new ClinicalNoteSnapshot();note.id="internal-note-id";when(db.find(any(Query.class),eq(ClinicalNoteSnapshot.class))).thenReturn(List.of(note));when(notes.read(anyString(),anyString(),anyString())).thenThrow(new IllegalStateException("sensitive-source-detail"));var packet=evidence.collect(p,"doctor");assertTrue(packet.sources.isEmpty());String facts=packet.facts.stream().map(a->a[1]).reduce("",String::concat);assertFalse(facts.contains("sensitive-source-detail"));assertTrue(facts.contains("不能据此判断无感染"));}
 @Test void longNotesAreExplicitlyPartialAndIdentityLinesAreExcluded(){String text=ClinicalNoteAiEvidence.minimize("姓名：合成姓名\n"+"合成原文".repeat(300)+"结尾需要核对",p);assertTrue(text.length()<700);assertTrue(text.contains("中间内容未提供"));assertTrue(text.contains("结尾需要核对"));assertFalse(text.contains("姓名"));}
 @Test void futureDocumentTimeCannotBecomeConfirmedCurrentFact(){var note=new ClinicalNoteSnapshot();note.id="future-synthetic-note";note.cryptoVersion=3;note.timeMeaning="documented";note.documentedAt=Instant.now().plusSeconds(3600);when(db.find(any(Query.class),eq(ClinicalNoteSnapshot.class))).thenReturn(List.of(note));when(notes.read(p.id,note.id,"doctor")).thenReturn(Map.of("body","合成内容：考虑感染，仍需核对。"));var packet=evidence.collect(p,"doctor");assertEquals(1,packet.sources.size());assertEquals(false,packet.sources.get(0).get("timeConfirmed"));assertNull(packet.sources.get(0).get("documentedAt"));}
 @Test void missingNotesExplainSyncParsingFailureInChineseWithoutRawPayload(){props.syncEnabled=true;var state=new ClinicalNoteSyncState();state.status="interface_response_invalid";when(notes.syncPatient(p)).thenReturn(state);when(db.find(any(Query.class),eq(ClinicalNoteSnapshot.class))).thenReturn(List.of());var packet=evidence.collect(p,"doctor");assertTrue(packet.missingReason.contains("JSON"));assertTrue(packet.missingReason.contains("语法"));assertFalse(packet.facts.stream().map(a->a[1]).reduce("",String::concat).contains("interface_response_invalid"));}
}
